# AUTO-GENERATED by Claude Code
# Purpose: inline chat (Alt+A, with the chat so far; as Copilot's Ctrl+I) for the Python cells and the SmashDb console's
#          SQL box: an instruction plus the editor's code (and selection) in, the rewritten code out.
#          The model gets the SmashDb tables (columns, first rows, notes on how values are written)
#          and, for Python, the session's live variables.
# Usage: POST /inline_edit (api.py), called from inline_edit.jsx; each call is one "agent" debug-log record,
#        with the same usage (tokens, cost, model requests) as a chat turn, its cost added to the session's.
# ---------------------------------------------------------------------------
from __future__ import annotations

import ast
import asyncio
import json
from dataclasses import dataclass
from typing import Any, Literal

import polars as pl
from pydantic import BaseModel, Field
from pydantic_ai import Agent, ModelRetry, RunContext, capture_run_messages

from ds.ai.smashdb import DATA_NOTES, MOVE_ALIASES
from ds.util.const import DEFAULT_AI_MODEL
from ds.util.logging import log_call, logger
from ds.util.text import clean_f_str

from . import logs
from .session import BUILTIN_NAMES, TurnUsage, find_session

# Context sent to the model is capped, so a namespace full of tables can't blow up the prompt.
MAX_VARIABLES = 40
MAX_COLUMNS = 30
SAMPLE_ROWS = 3  # rows shown of each table and DataFrame
MAX_VALUE_CHARS = 60  # a text value in those rows
# times a proposal that fails its check (check_proposal) is sent back to the model to fix; after
# that it is shown as it is
MAX_FIXES = 2

Language = Literal["python", "sql"]


class InlineEdit(BaseModel):
    code: str = Field(description="The replacement code only: no explanation, no Markdown fences.")


_INSTRUCTIONS = clean_f_str("""
    You edit code inside a small editor in a Super Smash Bros. Ultimate data app, as an inline code
    assistant (like Copilot's inline chat). You get the editor's code, the user's instruction and the
    data the code can use. Return only the code that replaces the target: the selected part when one is
    marked, else the editor's whole content. Keep the user's code and style where the instruction doesn't
    ask to change it, and use only tables, columns and variables that are listed. Write values as the
    data has them (see the first rows and the notes), not as the user's shorthand. Earlier messages,
    when there are any, are the user's chat with the app's assistant (its answers and tool results): use
    them to understand what the user means, eg "the players we just looked at".
    """)


@dataclass
class EditRun:
    """One inline edit, for the proposal check."""

    language: Language
    whole: bool
    """The proposal is the editor's whole text (not a replacement for a selection)."""
    db: Any = None
    """The session's SmashDb, to try a query on."""
    fixes: int = 0


edit_agent = Agent(
    DEFAULT_AI_MODEL,
    # on its Logfire spans (gen_ai.agent.name): the debug panel's Spend tab lists it apart from the chat
    name="inline-edit",
    # resolved at run time, so importing the app works without a key (as ds.ai.agent)
    defer_model_check=True,
    instructions=_INSTRUCTIONS,
    output_type=InlineEdit,
    deps_type=EditRun,
    retries=MAX_FIXES,
)


def proposal_problem(run: EditRun, code: str) -> str:
    """What is wrong with a proposal, "" when nothing was found. Only a whole text can be checked
    (a replacement for a selection is a fragment): a query is run on the db (reading local parquet;
    polars SQL supports less than the PostgreSQL the model tends to write), Python is only parsed
    (running it would change the user's variables).
    """
    if not run.whole or not code.strip():
        return ""
    if run.language == "python":
        try:
            ast.parse(code)
        except SyntaxError as error:
            return f"That is not valid Python: {error}"
        return ""
    if run.db is None:
        return ""
    try:
        rows = run.db.sql(code.strip().rstrip(";")).height
    except Exception as error:  # noqa: BLE001  # whatever polars raises is what the model must fix
        text = str(error).split("Resolved plan until failure")[0].strip()
        return f"That query fails in polars SQL (it supports less than PostgreSQL): {type(error).__name__}: {text}"
    if rows == 0:
        return (
            "That query runs but returns no rows. If that is not what the user wants, check the values it filters on."
        )
    return ""


@edit_agent.output_validator
async def check_proposal(ctx: RunContext[EditRun], output: InlineEdit) -> InlineEdit:
    """Send a proposal that doesn't work back to the model, up to MAX_FIXES times; then show it anyway."""
    run = ctx.deps
    if run.fixes >= MAX_FIXES:
        return output
    # off the event loop: a query can take a moment
    problem = await asyncio.to_thread(proposal_problem, run, output.code)
    if problem:
        run.fixes += 1
        raise ModelRetry(f"{problem} Send the corrected code.")
    return output


def _columns(columns: dict[str, Any] | list[str]) -> str:
    items = [f"{name} {dtype}" for name, dtype in columns.items()] if isinstance(columns, dict) else list(columns)
    more = f", ... {len(items) - MAX_COLUMNS} more" if len(items) > MAX_COLUMNS else ""
    return ", ".join(items[:MAX_COLUMNS]) + more


def _sample(df: pl.DataFrame) -> str:
    """The first rows as JSON lines, long text cut: names and types alone don't show how values are
    written (a move is 'Neutral Air', not 'nair'; a startup is the text '10/13/16')."""
    rows = []
    for row in df.head(SAMPLE_ROWS).select(df.columns[:MAX_COLUMNS]).iter_rows(named=True):
        short = {
            name: v[:MAX_VALUE_CHARS] + "…" if isinstance(v, str) and len(v) > MAX_VALUE_CHARS else v
            for name, v in row.items()
        }
        rows.append("    " + json.dumps(short, default=str, ensure_ascii=False))
    return "\n".join(rows)


def _table(name: str, columns: dict[str, Any] | list[str], rows: pl.DataFrame | None) -> str:
    lines = [f"- {name}({_columns(columns)})"]
    if rows is not None and rows.height:
        lines += ["  first rows:", _sample(rows)]
    return "\n".join(lines)


def _tables(schema: dict[str, Any], db: Any = None) -> str:
    """Every table with its columns, and its first rows when there is a db to read them from."""
    tables = []
    for name, columns in schema.items():
        rows = None
        if db is not None:
            try:
                rows = db.sql(f'select * from "{name}" limit {SAMPLE_ROWS}')
            except Exception:  # noqa: BLE001  # a table that can't be read is still listed
                rows = None
        tables.append(_table(name, columns, rows))
    return "\n".join(tables) or "(none)"


def _variables(namespace: dict[str, Any]) -> str:
    """The user's live variables: a DataFrame with its shape, columns and first rows, anything else by type."""
    lines = []
    for name, value in namespace.items():
        if name.startswith("_") or name in BUILTIN_NAMES or type(value).__name__ == "module":
            continue
        if isinstance(value, pl.DataFrame):
            lines.append(_table(f"{name}: polars DataFrame {value.height} x {value.width}", dict(value.schema), value))
        else:
            lines.append(f"- {name}: {type(value).__name__}")
    more = [f"- ... {len(lines) - MAX_VARIABLES} more"] if len(lines) > MAX_VARIABLES else []
    return "\n".join(lines[:MAX_VARIABLES] + more) or "(none yet)"


def _data_notes() -> str:
    """How SmashDb's values are written (shared with the chat's SmashDb tools, ds.ai.smashdb)."""
    aliases = ", ".join(f"{short} = '{full}'" for short, full in MOVE_ALIASES.items())
    return "\n".join([DATA_NOTES, f"framedata.move holds full move names, not player shorthand: {aliases}."])


def context(language: Language, token: str, schema: dict[str, Any] | None) -> str:
    """What the code can use: for SQL the tables it queries, for Python the session's variables and db.

    Built from parts joined by newlines (not one f-string): the tables and variables span lines.
    """
    session = find_session(token)
    db = session.db if session else None
    # the session's db knows the column types and has rows to show; without one (an unknown
    # token), the column names the editor sent
    tables = _tables(db.schema(), db) if db is not None else _tables(schema or {})
    if language == "sql":
        intro = "Language: polars SQL (PostgreSQL syntax), run as one query against these SmashDb tables:"
        return "\n".join([intro, tables, "About the data:", _data_notes()])
    intro = clean_f_str("""
        Language: Python, one cell of a Jupyter-like notebook with a persistent namespace. A bare
        expression on the last line is shown as the result. `pl` is polars. `db` is the SmashDb:
        `db.sql("select ...")` runs polars SQL and returns a polars DataFrame.
        """)
    variables = _variables(session.namespace if session else {})
    return "\n".join([intro, "Live variables:", variables, "SmashDb tables:", tables, "About the data:", _data_notes()])


def prompt(before: str, selected: str, after: str, instruction: str, previous: str = "") -> str:
    """The editor's code with the target marked, the instruction, and the last proposal when refining."""
    if selected:
        marked = f"{before}<selection>{selected}</selection>{after}"
        target = "Return only the code that replaces the part between <selection> and </selection>."
    else:
        marked = before + after
        target = "Return the editor's whole new content (it may be empty: then write the code from scratch)."
    parts = [f"Editor code:\n```\n{marked}\n```", target, f"Instruction: {instruction}"]
    if previous:
        parts.insert(2, f"Your last proposal, which the user wants changed:\n```\n{previous}\n```")
    return "\n\n".join(parts)


async def edit(body: dict[str, Any]) -> dict[str, str]:
    """{code} on success, {error} when the model or the request failed (shown in the inline box);
    with {usage}, what the call used (TurnUsage.summary), when it reached the model."""
    language: Language = "sql" if body.get("language") == "sql" else "python"
    token = str(body.get("token", ""))
    # the editor's text in three pieces (the middle one is the selection, "" when there is none)
    before, selected, after = (str(body.get(part) or "") for part in ("before", "selected", "after"))
    instruction = str(body.get("instruction", "")).strip()
    if not instruction:
        return {"error": "Type what to change first."}
    request = prompt(before, selected, after, instruction, str(body.get("previous") or ""))
    text = "\n\n".join([context(language, token, body.get("schema")), request])
    # the chat so far goes along (read only: the inline call is not added to the chat)
    session = find_session(token)
    history = list(session.ai_history) if session else []
    run = EditRun(language=language, whole=not selected, db=session.db if session else None)
    name = f"inline edit ({language})"
    with (
        logger.contextualize(session=logs.session_id(token), origin="inline edit"),
        log_call("agent", "inline-edit", name=name, prompt=instruction) as call,
        capture_run_messages() as captured,
    ):
        answer: dict[str, str] = {}
        try:
            result = await edit_agent.run(text, message_history=history, deps=run)
            answer["code"] = result.output.code
        except Exception as error:  # noqa: BLE001  # shown in the inline box, not raised into the request
            call["error"] = answer["error"] = f"{type(error).__name__}: {error}"
        # from the messages, as a chat turn does (Session.ask), so a failed call still shows what it spent
        usage = TurnUsage.of(captured[len(history) :])
        usage.log_to(call)
        call["fixes"] = run.fixes  # proposals sent back to the model because they failed the check
        if session:
            session.ai_cost += usage.cost or 0
        if usage.requests:
            answer["usage"] = usage.summary()
    return answer
